import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import {
  generateRequestKey,
  RequestCache,
  deduplicate,
  getStats,
  resetStats,
  type DeduplicationOptions,
} from './requestDeduplicator';

describe('Request Deduplicator', () => {
  describe('generateRequestKey', () => {
    it('should generate consistent keys for identical requests', () => {
      const key1 = generateRequestKey('/api/generate', 'POST', { prompt: 'hello', model: 'gpt-4' });
      const key2 = generateRequestKey('/api/generate', 'POST', { prompt: 'hello', model: 'gpt-4' });
      expect(key1).toBe(key2);
    });

    it('should generate same key regardless of property order', () => {
      const key1 = generateRequestKey('/api/generate', 'POST', { prompt: 'hello', model: 'gpt-4' });
      const key2 = generateRequestKey('/api/generate', 'POST', { model: 'gpt-4', prompt: 'hello' });
      expect(key1).toBe(key2);
    });

    it('should normalize HTTP method to uppercase', () => {
      const key1 = generateRequestKey('/api/data', 'post', { id: 1 });
      const key2 = generateRequestKey('/api/data', 'POST', { id: 1 });
      expect(key1).toBe(key2);
    });

    it('should handle requests without body', () => {
      const key = generateRequestKey('/api/user', 'GET');
      expect(key).toBe('GET::/api/user');
    });

    it('should handle nested objects in body', () => {
      const body = {
        user: { name: 'John', settings: { theme: 'dark' } },
        data: [1, 2, 3],
      };
      const key1 = generateRequestKey('/api/update', 'POST', body);
      const key2 = generateRequestKey('/api/update', 'POST', {
        data: [1, 2, 3],
        user: { settings: { theme: 'dark' }, name: 'John' },
      });
      expect(key1).toBe(key2);
    });

    it('should handle arrays in body', () => {
      const key1 = generateRequestKey('/api/bulk', 'POST', { items: [1, 2, 3] });
      const key2 = generateRequestKey('/api/bulk', 'POST', { items: [1, 2, 3] });
      expect(key1).toBe(key2);
    });

    it('should generate different keys for different endpoints', () => {
      const key1 = generateRequestKey('/api/generate', 'POST', { prompt: 'hello' });
      const key2 = generateRequestKey('/api/chat', 'POST', { prompt: 'hello' });
      expect(key1).not.toBe(key2);
    });

    it('should generate different keys for different methods', () => {
      const key1 = generateRequestKey('/api/data', 'GET', { id: 1 });
      const key2 = generateRequestKey('/api/data', 'POST', { id: 1 });
      expect(key1).not.toBe(key2);
    });

    it('should generate different keys for different bodies', () => {
      const key1 = generateRequestKey('/api/generate', 'POST', { prompt: 'hello' });
      const key2 = generateRequestKey('/api/generate', 'POST', { prompt: 'world' });
      expect(key1).not.toBe(key2);
    });

    it('should handle null body', () => {
      const key = generateRequestKey('/api/data', 'POST', null);
      expect(key).toBe('POST::/api/data');
    });

    it('should handle undefined body', () => {
      const key = generateRequestKey('/api/data', 'POST', undefined);
      expect(key).toBe('POST::/api/data');
    });

    it('should handle special characters in strings', () => {
      const body = { text: 'Hello "world" with \n newlines & special chars' };
      const key = generateRequestKey('/api/process', 'POST', body);
      expect(key).toContain('POST::/api/process::');
      expect(key).toBeDefined();
    });

    it('should handle primitive values in body', () => {
      const key1 = generateRequestKey('/api/data', 'POST', { count: 42 });
      const key2 = generateRequestKey('/api/data', 'POST', { count: 42 });
      expect(key1).toBe(key2);
    });

    it('should handle boolean values in body', () => {
      const key1 = generateRequestKey('/api/settings', 'POST', { enabled: true });
      const key2 = generateRequestKey('/api/settings', 'POST', { enabled: true });
      expect(key1).toBe(key2);
    });

    it('should handle deeply nested objects', () => {
      const body = {
        level1: {
          level2: {
            level3: {
              level4: { value: 'deep' },
            },
          },
        },
      };
      const key1 = generateRequestKey('/api/deep', 'POST', body);
      const key2 = generateRequestKey('/api/deep', 'POST', body);
      expect(key1).toBe(key2);
    });

    it('should handle non-serializable objects gracefully', () => {
      const consoleWarnSpy = vi.spyOn(console, 'warn').mockImplementation(() => {});
      const circular: Record<string, unknown> = { a: 1 };
      circular.self = circular; // Create circular reference

      const key = generateRequestKey('/api/test', 'POST', circular);
      expect(key).toBeDefined();
      expect(consoleWarnSpy).toHaveBeenCalled();

      consoleWarnSpy.mockRestore();
    });
  });

  describe('RequestCache', () => {
    let cache: RequestCache<string>;

    beforeEach(() => {
      cache = new RequestCache<string>();
    });

    afterEach(() => {
      cache.clear();
    });

    describe('set and get', () => {
      it('should store and retrieve promises', () => {
        const promise = Promise.resolve('test data');
        cache.set('test-key', promise);

        const retrieved = cache.get('test-key');
        expect(retrieved).toBe(promise);
      });

      it('should return undefined for non-existent keys', () => {
        const retrieved = cache.get('non-existent');
        expect(retrieved).toBeUndefined();
      });

      it('should overwrite existing entries', () => {
        const promise1 = Promise.resolve('first');
        const promise2 = Promise.resolve('second');

        cache.set('key', promise1);
        cache.set('key', promise2);

        const retrieved = cache.get('key');
        expect(retrieved).toBe(promise2);
      });
    });

    describe('has', () => {
      it('should return true for existing keys', () => {
        const promise = Promise.resolve('data');
        cache.set('key', promise);
        expect(cache.has('key')).toBe(true);
      });

      it('should return false for non-existent keys', () => {
        expect(cache.has('non-existent')).toBe(false);
      });
    });

    describe('delete', () => {
      it('should remove entries from cache', () => {
        const promise = Promise.resolve('data');
        cache.set('key', promise);

        expect(cache.has('key')).toBe(true);
        const deleted = cache.delete('key');

        expect(deleted).toBe(true);
        expect(cache.has('key')).toBe(false);
      });

      it('should return false when deleting non-existent key', () => {
        const deleted = cache.delete('non-existent');
        expect(deleted).toBe(false);
      });

      it('should clear timeout when deleting entry', () => {
        vi.useFakeTimers();
        const promise = Promise.resolve('data');
        const timeoutId = setTimeout(() => {}, 1000);

        cache.set('key', promise, timeoutId);
        cache.delete('key');

        vi.advanceTimersByTime(1000);
        // If timeout was properly cleared, no issues should occur
        expect(cache.has('key')).toBe(false);

        vi.useRealTimers();
      });
    });

    describe('size', () => {
      it('should return 0 for empty cache', () => {
        expect(cache.size()).toBe(0);
      });

      it('should return correct count of entries', () => {
        cache.set('key1', Promise.resolve('data1'));
        cache.set('key2', Promise.resolve('data2'));
        cache.set('key3', Promise.resolve('data3'));

        expect(cache.size()).toBe(3);
      });

      it('should update count after deletion', () => {
        cache.set('key1', Promise.resolve('data1'));
        cache.set('key2', Promise.resolve('data2'));

        expect(cache.size()).toBe(2);

        cache.delete('key1');
        expect(cache.size()).toBe(1);
      });
    });

    describe('clear', () => {
      it('should remove all entries', () => {
        cache.set('key1', Promise.resolve('data1'));
        cache.set('key2', Promise.resolve('data2'));
        cache.set('key3', Promise.resolve('data3'));

        expect(cache.size()).toBe(3);

        cache.clear();
        expect(cache.size()).toBe(0);
        expect(cache.has('key1')).toBe(false);
        expect(cache.has('key2')).toBe(false);
        expect(cache.has('key3')).toBe(false);
      });

      it('should clear all timeouts', () => {
        vi.useFakeTimers();

        const timeout1 = setTimeout(() => {}, 1000);
        const timeout2 = setTimeout(() => {}, 2000);

        cache.set('key1', Promise.resolve('data1'), timeout1);
        cache.set('key2', Promise.resolve('data2'), timeout2);

        cache.clear();

        vi.advanceTimersByTime(3000);
        // If timeouts were properly cleared, no issues should occur

        vi.useRealTimers();
      });
    });

    describe('keys', () => {
      it('should return empty array for empty cache', () => {
        const keys = cache.keys();
        expect(keys).toEqual([]);
      });

      it('should return all cache keys', () => {
        cache.set('key1', Promise.resolve('data1'));
        cache.set('key2', Promise.resolve('data2'));
        cache.set('key3', Promise.resolve('data3'));

        const keys = cache.keys();
        expect(keys).toHaveLength(3);
        expect(keys).toContain('key1');
        expect(keys).toContain('key2');
        expect(keys).toContain('key3');
      });
    });
  });

  describe('deduplicate', () => {
    beforeEach(() => {
      vi.clearAllMocks();
    });

    describe('basic deduplication', () => {
      it('should execute request only once for concurrent identical requests', async () => {
        const executor = vi.fn().mockResolvedValue('result');

        const promise1 = deduplicate(executor, '/api/test', 'POST', { data: 'test' });
        const promise2 = deduplicate(executor, '/api/test', 'POST', { data: 'test' });
        const promise3 = deduplicate(executor, '/api/test', 'POST', { data: 'test' });

        const results = await Promise.all([promise1, promise2, promise3]);

        expect(executor).toHaveBeenCalledTimes(1);
        expect(results).toEqual(['result', 'result', 'result']);
      });

      it('should return same promise instance for concurrent identical requests', () => {
        const executor = vi.fn().mockResolvedValue('result');

        const promise1 = deduplicate(executor, '/api/test', 'POST', { data: 'test' });
        const promise2 = deduplicate(executor, '/api/test', 'POST', { data: 'test' });

        expect(promise1).toBe(promise2);
      });

      it('should execute separate requests for different parameters', async () => {
        const executor = vi.fn().mockResolvedValue('result');

        const promise1 = deduplicate(executor, '/api/test', 'POST', { data: 'test1' });
        const promise2 = deduplicate(executor, '/api/test', 'POST', { data: 'test2' });

        await Promise.all([promise1, promise2]);

        expect(executor).toHaveBeenCalledTimes(2);
      });

      it('should allow new request after previous completes', async () => {
        const executor = vi.fn().mockResolvedValue('result');

        const result1 = await deduplicate(executor, '/api/test', 'POST', { data: 'test' });
        expect(result1).toBe('result');

        const result2 = await deduplicate(executor, '/api/test', 'POST', { data: 'test' });
        expect(result2).toBe('result');

        expect(executor).toHaveBeenCalledTimes(2);
      });
    });

    describe('cache cleanup', () => {
      it('should clean up cache on successful request', async () => {
        const executor = vi.fn().mockResolvedValue('success');
        const cache = new RequestCache();

        await deduplicate(executor, '/api/test', 'POST', { data: 'test' });

        // Cache should be cleaned up after request completes
        const key = generateRequestKey('/api/test', 'POST', { data: 'test' });
        expect(cache.has(key)).toBe(false);
      });

      it('should clean up cache on failed request', async () => {
        const executor = vi.fn().mockRejectedValue(new Error('Request failed'));

        try {
          await deduplicate(executor, '/api/test', 'POST', { data: 'test' });
        } catch (error) {
          // Expected error
        }

        // Cache should be cleaned up after request fails
        const cache = new RequestCache();
        const key = generateRequestKey('/api/test', 'POST', { data: 'test' });
        expect(cache.has(key)).toBe(false);
      });

      it('should propagate errors to all concurrent callers', async () => {
        const testError = new Error('Request failed');
        const executor = vi.fn().mockRejectedValue(testError);

        const promise1 = deduplicate(executor, '/api/test', 'POST', { data: 'test' });
        const promise2 = deduplicate(executor, '/api/test', 'POST', { data: 'test' });
        const promise3 = deduplicate(executor, '/api/test', 'POST', { data: 'test' });

        await expect(promise1).rejects.toThrow('Request failed');
        await expect(promise2).rejects.toThrow('Request failed');
        await expect(promise3).rejects.toThrow('Request failed');

        expect(executor).toHaveBeenCalledTimes(1);
      });
    });

    describe('timeout mechanism', () => {
      it('should clean up cache after timeout', async () => {
        vi.useFakeTimers();

        const executor = vi.fn().mockImplementation(
          () => new Promise((resolve) => setTimeout(() => resolve('result'), 60000))
        );

        const options: DeduplicationOptions = { timeout: 30000 };
        deduplicate(executor, '/api/test', 'POST', { data: 'test' }, options);

        // Advance time past timeout
        vi.advanceTimersByTime(31000);

        // Cache should be cleaned up
        const cache = new RequestCache();
        const key = generateRequestKey('/api/test', 'POST', { data: 'test' });
        expect(cache.has(key)).toBe(false);

        vi.useRealTimers();
      });

      it('should use default timeout of 30 seconds', async () => {
        vi.useFakeTimers();

        const executor = vi.fn().mockImplementation(
          () => new Promise((resolve) => setTimeout(() => resolve('result'), 60000))
        );

        deduplicate(executor, '/api/test', 'POST', { data: 'test' });

        // Advance time to just before default timeout
        vi.advanceTimersByTime(29000);
        // Cache should still exist
        let cache = new RequestCache();
        let key = generateRequestKey('/api/test', 'POST', { data: 'test' });
        // Note: We can't reliably check this as cache is global

        // Advance past default timeout
        vi.advanceTimersByTime(2000);

        vi.useRealTimers();
      });

      it('should allow custom timeout configuration', async () => {
        vi.useFakeTimers();

        const executor = vi.fn().mockImplementation(
          () => new Promise((resolve) => setTimeout(() => resolve('result'), 10000))
        );

        const options: DeduplicationOptions = { timeout: 5000 };
        deduplicate(executor, '/api/test', 'POST', { data: 'test' }, options);

        // Advance time past custom timeout
        vi.advanceTimersByTime(6000);

        vi.useRealTimers();
      });
    });

    describe('custom key generator', () => {
      it('should use custom key generator when provided', async () => {
        const customKeyGen = vi.fn().mockReturnValue('custom-key');
        const executor = vi.fn().mockResolvedValue('result');

        const options: DeduplicationOptions = { keyGenerator: customKeyGen };

        await deduplicate(executor, '/api/test', 'POST', { data: 'test' }, options);

        expect(customKeyGen).toHaveBeenCalledWith('/api/test', 'POST', { data: 'test' });
      });

      it('should deduplicate using custom key generator', async () => {
        const customKeyGen = () => 'same-key-for-all';
        const executor = vi.fn().mockResolvedValue('result');

        const options: DeduplicationOptions = { keyGenerator: customKeyGen };

        // Different requests but same custom key
        const promise1 = deduplicate(executor, '/api/test1', 'POST', { data: 'test1' }, options);
        const promise2 = deduplicate(executor, '/api/test2', 'POST', { data: 'test2' }, options);

        await Promise.all([promise1, promise2]);

        // Should only execute once because custom key is identical
        expect(executor).toHaveBeenCalledTimes(1);
      });
    });

    describe('debug logging', () => {
      it('should log cache hits when debug is enabled', async () => {
        const consoleLogSpy = vi.spyOn(console, 'log').mockImplementation(() => {});
        const executor = vi.fn().mockResolvedValue('result');

        const options: DeduplicationOptions = { debug: true };

        const promise1 = deduplicate(executor, '/api/test', 'POST', { data: 'test' }, options);
        const promise2 = deduplicate(executor, '/api/test', 'POST', { data: 'test' }, options);

        await Promise.all([promise1, promise2]);

        expect(consoleLogSpy).toHaveBeenCalledWith(
          expect.stringContaining('[Dedup] Cache MISS'),
          expect.any(String)
        );
        expect(consoleLogSpy).toHaveBeenCalledWith(
          expect.stringContaining('[Dedup] Cache HIT'),
          expect.any(String)
        );

        consoleLogSpy.mockRestore();
      });

      it('should log cleanup on success when debug is enabled', async () => {
        const consoleLogSpy = vi.spyOn(console, 'log').mockImplementation(() => {});
        const executor = vi.fn().mockResolvedValue('result');

        const options: DeduplicationOptions = { debug: true };

        await deduplicate(executor, '/api/test', 'POST', { data: 'test' }, options);

        expect(consoleLogSpy).toHaveBeenCalledWith(
          expect.stringContaining('[Dedup] Request succeeded'),
          expect.any(String)
        );

        consoleLogSpy.mockRestore();
      });

      it('should log errors when debug is enabled', async () => {
        const consoleErrorSpy = vi.spyOn(console, 'error').mockImplementation(() => {});
        const executor = vi.fn().mockRejectedValue(new Error('Test error'));

        const options: DeduplicationOptions = { debug: true };

        try {
          await deduplicate(executor, '/api/test', 'POST', { data: 'test' }, options);
        } catch (error) {
          // Expected error
        }

        expect(consoleErrorSpy).toHaveBeenCalledWith(
          expect.stringContaining('[Dedup] Request failed'),
          expect.any(String),
          expect.any(Error)
        );

        consoleErrorSpy.mockRestore();
      });
    });

    describe('error scenarios', () => {
      it('should handle network errors correctly', async () => {
        const networkError = new Error('Network request failed');
        const executor = vi.fn().mockRejectedValue(networkError);

        await expect(
          deduplicate(executor, '/api/test', 'POST', { data: 'test' })
        ).rejects.toThrow('Network request failed');
      });

      it('should handle API errors correctly', async () => {
        const apiError = new Error('API Error: Invalid request');
        const executor = vi.fn().mockRejectedValue(apiError);

        await expect(
          deduplicate(executor, '/api/test', 'POST', { data: 'test' })
        ).rejects.toThrow('API Error: Invalid request');
      });

      it('should handle synchronous executor errors', () => {
        const consoleErrorSpy = vi.spyOn(console, 'error').mockImplementation(() => {});
        const executor = vi.fn().mockImplementation(() => {
          throw new Error('Synchronous error');
        });

        const options: DeduplicationOptions = { debug: true };

        expect(() => deduplicate(executor, '/api/test', 'POST', { data: 'test' }, options)).toThrow(
          'Synchronous error'
        );

        consoleErrorSpy.mockRestore();
      });

      it('should not cache synchronous errors', () => {
        let callCount = 0;
        const executor = vi.fn().mockImplementation(() => {
          callCount++;
          if (callCount === 1) {
            throw new Error('First call fails synchronously');
          }
          return Promise.resolve('success');
        });

        // First call throws synchronously
        expect(() => deduplicate(executor, '/api/test', 'POST', { data: 'test' })).toThrow(
          'First call fails synchronously'
        );

        // Second call should execute (not cached)
        const promise = deduplicate(executor, '/api/test', 'POST', { data: 'test' });
        expect(promise).toBeInstanceOf(Promise);
      });

      it('should handle timeout errors in executor', async () => {
        const timeoutError = new Error('Request timeout');
        const executor = vi.fn().mockRejectedValue(timeoutError);

        await expect(
          deduplicate(executor, '/api/test', 'POST', { data: 'test' })
        ).rejects.toThrow('Request timeout');
      });
    });

    describe('type safety', () => {
      it('should maintain type safety for response', async () => {
        interface ApiResponse {
          id: number;
          name: string;
        }

        const executor = vi.fn().mockResolvedValue({ id: 1, name: 'Test' });

        const result = await deduplicate<ApiResponse>(
          executor,
          '/api/test',
          'GET',
          undefined
        );

        expect(result.id).toBe(1);
        expect(result.name).toBe('Test');
      });

      it('should work with different response types', async () => {
        const stringExecutor = vi.fn().mockResolvedValue('string result');
        const stringResult = await deduplicate<string>(
          stringExecutor,
          '/api/string',
          'GET',
          undefined
        );
        expect(typeof stringResult).toBe('string');

        const numberExecutor = vi.fn().mockResolvedValue(42);
        const numberResult = await deduplicate<number>(
          numberExecutor,
          '/api/number',
          'GET',
          undefined
        );
        expect(typeof numberResult).toBe('number');

        const booleanExecutor = vi.fn().mockResolvedValue(true);
        const booleanResult = await deduplicate<boolean>(
          booleanExecutor,
          '/api/boolean',
          'GET',
          undefined
        );
        expect(typeof booleanResult).toBe('boolean');
      });
    });

    describe('concurrent request edge cases', () => {
      it('should handle rapid sequential requests', async () => {
        const executor = vi.fn().mockResolvedValue('result');

        const promises = Array.from({ length: 10 }, () =>
          deduplicate(executor, '/api/test', 'POST', { data: 'test' })
        );

        await Promise.all(promises);

        expect(executor).toHaveBeenCalledTimes(1);
      });

      it('should handle mixed success and error scenarios', async () => {
        let callCount = 0;
        const executor = vi.fn().mockImplementation(() => {
          callCount++;
          if (callCount === 1) {
            return Promise.reject(new Error('First batch fails'));
          }
          return Promise.resolve('success');
        });

        // First batch - all fail together
        const batch1Promises = [
          deduplicate(executor, '/api/test', 'POST', { data: 'test' }),
          deduplicate(executor, '/api/test', 'POST', { data: 'test' }),
        ];

        await expect(Promise.all(batch1Promises)).rejects.toThrow('First batch fails');

        // Wait for cleanup
        await new Promise((resolve) => setTimeout(resolve, 10));

        // Second batch - should succeed
        const batch2Promises = [
          deduplicate(executor, '/api/test', 'POST', { data: 'test' }),
          deduplicate(executor, '/api/test', 'POST', { data: 'test' }),
        ];

        const results = await Promise.all(batch2Promises);
        expect(results).toEqual(['success', 'success']);
      });

      it('should handle requests with no timeout (timeout = 0)', async () => {
        const executor = vi.fn().mockResolvedValue('result');
        const options: DeduplicationOptions = { timeout: 0 };

        const result = await deduplicate(executor, '/api/test', 'POST', { data: 'test' }, options);

        expect(result).toBe('result');
        expect(executor).toHaveBeenCalledTimes(1);
      });
    });

    describe('Metrics Tracking', () => {
      beforeEach(() => {
        // Reset stats before each test
        resetStats();
      });

      it('should track cache hits', async () => {
        const executor = vi.fn().mockResolvedValue('result');

        // First call - should be a miss
        await deduplicate(executor, '/api/test', 'POST', { data: 'test' });

        // Wait for cleanup
        await new Promise((resolve) => setTimeout(resolve, 10));

        let stats = getStats();
        expect(stats.misses).toBe(1);
        expect(stats.hits).toBe(0);
        expect(stats.saved).toBe(0);

        // Concurrent calls - should be hits
        const promises = [
          deduplicate(executor, '/api/test', 'POST', { data: 'test' }),
          deduplicate(executor, '/api/test', 'POST', { data: 'test' }),
          deduplicate(executor, '/api/test', 'POST', { data: 'test' }),
        ];

        await Promise.all(promises);

        stats = getStats();
        expect(stats.misses).toBe(2); // First call + one for the concurrent batch
        expect(stats.hits).toBe(2); // Two concurrent calls hit the cache
        expect(stats.saved).toBe(2); // Two API calls saved
      });

      it('should track cache misses', async () => {
        const executor = vi.fn().mockResolvedValue('result');

        await deduplicate(executor, '/api/test1', 'POST', { data: 'test1' });
        await deduplicate(executor, '/api/test2', 'POST', { data: 'test2' });
        await deduplicate(executor, '/api/test3', 'POST', { data: 'test3' });

        const stats = getStats();
        expect(stats.misses).toBe(3);
        expect(stats.hits).toBe(0);
        expect(stats.saved).toBe(0);
      });

      it('should track in-flight requests', async () => {
        let resolveExecutor: (value: string) => void;
        const executor = vi.fn().mockImplementation(
          () =>
            new Promise<string>((resolve) => {
              resolveExecutor = resolve;
            })
        );

        // Start requests but don't wait for them
        const promises = [
          deduplicate(executor, '/api/test', 'POST', { data: 'test' }),
          deduplicate(executor, '/api/test', 'POST', { data: 'test' }),
          deduplicate(executor, '/api/test', 'POST', { data: 'test' }),
        ];

        // Check in-flight count while requests are pending
        const statsDuringFlight = getStats();
        expect(statsDuringFlight.inFlight).toBe(1); // Only 1 actual request in-flight

        // Resolve the requests
        resolveExecutor!('result');
        await Promise.all(promises);

        // Wait for cleanup
        await new Promise((resolve) => setTimeout(resolve, 10));

        // Check in-flight count after completion
        const statsAfterCompletion = getStats();
        expect(statsAfterCompletion.inFlight).toBe(0);
      });

